1://! Inspector-Gadget-compatible JSON introspection for element coverage.
2://!
3://! Default build embeds the JSON walk used by
4://! `op_inspector::introspective_gadget::JsonParser` — but **recurse into nested
5://! objects/arrays** (upstream `analyze_json_value` leaves `nested_schema: None`,
6://! so a straight call would miss deep elements).
7://!
8://! With `--features inspector-gadget`, also invoke the live
9://! `IntrospectiveGadget::inspect_object` and merge its top-level property names.
10:
11:use anyhow::{Context, Result};
12:use serde_json::Value;
13:use std::collections::BTreeSet;
14:
15:/// Flatten a JSON value into dotted element paths.
16:/// Arrays use `[*]` for the item shape (first element, or empty marker).
17:pub fn introspect_json_paths(value: &Value) -> BTreeSet<String> {
18:    let mut out = BTreeSet::new();
19:    walk(value, "", &mut out);
20:    out
21:}
22:
23:fn walk(value: &Value, prefix: &str, out: &mut BTreeSet<String>) {
24:    match value {
25:        Value::Object(map) => {
26:            if !prefix.is_empty() {
27:                out.insert(prefix.to_string());
28:            }
29:            for (k, v) in map {
30:                let path = if prefix.is_empty() {
31:                    k.clone()
32:                } else {
33:                    format!("{prefix}.{k}")
34:                };
35:                out.insert(path.clone());
36:                walk(v, &path, out);
37:            }
38:        }
